python3 - <<'EOF'
import os,re,collections
root="AlgebraicJacobian"
def mod2path(m):
    return m.replace(".","/")+".lean"
imports=collections.defaultdict(list)
for dp,_,fns in os.walk(root):
    for fn in fns:
        if fn.endswith(".lean"):
            p=os.path.join(dp,fn)
            mod=p[:-5].replace("/",".")
            for line in open(p,encoding="utf8"):
                m=re.match(r"^import\s+(\S+)",line)
                if m: imports[mod].append(m.group(1))
# root file
rootmod="AlgebraicJacobian"
seen=set()
stack=[]
for line in open("AlgebraicJacobian.lean",encoding="utf8"):
    m=re.match(r"^import\s+(\S+)",line)
    if m: stack.append(m.group(1))
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    stack.extend(imports.get(m,[]))
allmods=set(imports.keys())
unreach=sorted(m for m in allmods if m not in seen)
print("total modules:",len(allmods),"reachable:",len(seen & allmods),"unreachable:",len(unreach))
for m in unreach: print("  UNREACHABLE",m)
EOF

